// Generic D&C template
function divideAndConquer(arr, lo, hi) {
  if (lo >= hi) return baseSolution(arr, lo, hi); // base case

  const mid = lo + Math.floor((hi - lo) / 2);

  const leftResult = divideAndConquer(arr, lo, mid);
  const rightResult = divideAndConquer(arr, mid + 1, hi);

  return combine(leftResult, rightResult, arr, lo, mid, hi);
}

// Merge sort with inversion count
function countInversions(arr) {
  let inversions = 0;

  function mergeSort(arr) {
    if (arr.length <= 1) return arr;
    const mid = Math.floor(arr.length / 2);
    const left = mergeSort(arr.slice(0, mid));
    const right = mergeSort(arr.slice(mid));
    return mergAndCount(left, right);
  }

  function mergAndCount(left, right) {
    const result = [];
    let i = 0, j = 0;
    while (i < left.length && j < right.length) {
      if (left[i] <= right[j]) {
        result.push(left[i++]);
      } else {
        // left[i..end] are all inversions with right[j]
        inversions += left.length - i;
        result.push(right[j++]);
      }
    }
    return result.concat(left.slice(i)).concat(right.slice(j));
  }

  mergeSort(arr);
  return inversions;
}
